const allItems = $input.all();
let lastValidData = {};

// Danh sách các cột chính cần kế thừa từ dòng trước nếu dòng hiện tại để trống
const MASTER_FIELDS = [
  "Mục đích chính",
  "Thông tin thương hiệu/sản phẩm/dịch vụ/USP",
  "Chân dung & Insight khách hàng",
  "Kênh triển khai",
  "Mục tiêu kinh doanh/marketing",
  "Mục tiêu đầu ra",
  "Định dạng nội dung",
  "Độ dài nội dung",
  "Số phiên bản nội dung",
  "Công thức nội dung (Copywriting formula)",
  "Văn phong",
  "Văn phong & Giọng điệu",
  "Hành động mong muốn (CTA)",
  "Tỷ lệ Văn nói - Văn viết",
  "Tỷ lệ Định tính - Định lượng",
  "Số liệu - bằng chứng uy tín",
  "Prompt bổ sung / luật riêng",
  "Kho Media Drive"
];

// Hàm quét lấy đại diện Chủ đề phễu từ tất cả các cột phễu (K, L, M, N)
function getFunnelTopic(row) {
  const keys = Object.keys(row);
  const IGNORE_VALUES = ["tùy ý", "200 từ", "300 từ", "caption", "bài viết"];

  for (const k of keys) {
    const kLower = k.toLowerCase().trim();
    if (
      kLower === "col_14" ||
      kLower === "col_13" ||
      kLower === "col_12" ||
      kLower === "col_11" ||
      kLower.includes("chủ đề phễu") ||
      kLower.includes("tuyến nội dung") ||
      kLower.includes("phễu lạnh") ||
      kLower.includes("phễu ấm") ||
      kLower.includes("phễu nóng")
    ) {
      const val = row[k];
      if (val !== undefined && val !== null) {
        const strVal = String(val).trim();
        if (
          strVal !== "" &&
          !strVal.startsWith("http") &&
          !strVal.startsWith("[Tùy chọn]") &&
          !IGNORE_VALUES.includes(strVal.toLowerCase())
        ) {
          return strVal;
        }
      }
    }
  }
  return "";
}

return allItems.map((item) => {
  const row = item.json;

  // 1. Cập nhật kế thừa các cột master
  MASTER_FIELDS.forEach((field) => {
    const val = row[field];
    if (val !== undefined && val !== null && String(val).trim() !== "") {
      lastValidData[field] = String(val).trim();
    }
  });

  // 2. Kế thừa Tiêu chuẩn ảnh 1, 2, 3
  const tc1 = row["Tiêu chuẩn ảnh 1"] || "";
  const tc2 = row["Tiêu chuẩn ảnh 2"] || row["col_30"] || "";
  const tc3 = row["Tiêu chuẩn ảnh 3"] || row["col_31"] || "";

  if (tc1) lastValidData["Tiêu chuẩn ảnh 1"] = String(tc1).trim();
  if (tc2) lastValidData["Tiêu chuẩn ảnh 2"] = String(tc2).trim();
  if (tc3) lastValidData["Tiêu chuẩn ảnh 3"] = String(tc3).trim();

  // 3. Kế thừa Chủ đề phễu
  const currentFunnel = getFunnelTopic(row);
  if (currentFunnel !== "") {
    lastValidData["Chủ đề phễu"] = currentFunnel;
  }

  // 4. Tạo JSON đầu ra
  const updatedRow = { ...row };

  MASTER_FIELDS.forEach((field) => {
    const currentVal = row[field];
    updatedRow[field] = (currentVal !== undefined && currentVal !== null && String(currentVal).trim() !== "")
      ? String(currentVal).trim()
      : (lastValidData[field] || "");
  });

  // Map chuẩn & dọn dẹp key Tiêu chuẩn ảnh (xoá col_30, col_31)
  updatedRow["Tiêu chuẩn ảnh 1"] = tc1 ? String(tc1).trim() : (lastValidData["Tiêu chuẩn ảnh 1"] || "");
  updatedRow["Tiêu chuẩn ảnh 2"] = tc2 ? String(tc2).trim() : (lastValidData["Tiêu chuẩn ảnh 2"] || "");
  updatedRow["Tiêu chuẩn ảnh 3"] = tc3 ? String(tc3).trim() : (lastValidData["Tiêu chuẩn ảnh 3"] || "");

  delete updatedRow["col_30"];
  delete updatedRow["col_31"];

  // Gán key Chủ đề phễu (Vẫn GIỮ LẠI các cột gốc col_11, col_12, col_13, col_14)
  updatedRow["Chủ đề phễu"] = currentFunnel !== "" 
    ? currentFunnel 
    : (lastValidData["Chủ đề phễu"] || "");

  // Đồng bộ Văn phong
  const vpVal = updatedRow["Văn phong"] || updatedRow["Văn phong & Giọng điệu"] || "";
  updatedRow["Văn phong"] = vpVal;
  updatedRow["Văn phong & Giọng điệu"] = vpVal;

  return {
    json: updatedRow
  };
});

// Node: Code chuẩn hóa 3 Options từ Gemini API để ghi vào Google Sheet
const items = $input.all();

return items.map((item, index) => {
  const j = item.json;

  // 1. TRÍCH XUẤT RAW TEXT TỪ GEMINI API OUTPUT
  let rawText = j.content?.parts?.[0]?.text
    || j.candidates?.[0]?.content?.parts?.[0]?.text
    || j.text 
    || j.output 
    || j.message?.content 
    || "";

  if (typeof rawText === 'object') {
    rawText = JSON.stringify(rawText);
  }

  // Làm sạch Markdown ```json ... ``` nếu Gemini tự bọc
  const cleanedText = String(rawText)
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  let parsed = {};
  try {
    parsed = JSON.parse(cleanedText);
  } catch (e) {
    // Nếu parse lỗi thì dùng rawText làm Option 1
  }

  // 2. LẤY ROW_NUMBER TỪ NODE XỦ LÝ TRƯỚC
  let rowId = $('Xử lý gom các nội dung trùng').first().json.row_number;

  // 3. LẤY LINK THƯ MỤC ẢNH DEMO (NẾU CÓ)
  let folderLink = "";
  try {
    folderLink = $('Tách ảnh từ nhiều link').itemMatching(index)?.json?.drive_folder_link || "";
  } catch (e) {}
  if (!folderLink) {
    folderLink = j["Kho Media Drive"] || j["Kho Media"] || j["Ảnh Demo"] || "";
  }

  // 4. BÓC TÁCH NỘI DUNG 3 OPTION & CHUẨN HÓA CÂU TỪ
  const op1 = parsed.option_1 || {};
  const op2 = parsed.option_2 || {};
  const op3 = parsed.option_3 || {};

  let hashtags = parsed.hashtags || "#GaAiCapVan #GaGiongSieuTrung #ChannuoiHieuQua #Ecolar";
  hashtags = String(hashtags)
    .replace(/NongNghiepEcolar/gi, "Ecolar")
    .replace(/NongNghiep/gi, "")
    .replace(/#+/g, "#")
    .trim();

  // KHỐI THÔNG TIN LIÊN HỆ CHÈN BỔ SUNG SAU HASHTAG
  const contactInfo = `-------------------------------------------
Ecolar – Lối sống xanh bền vững
🌐 Website: https://ecolar.vn/
📞Hotline: 0868 515 668
📧Email: lienhe@ecolar.vn
📘Zalo OA: https://zalo.me/1699772582506373938
 ⓕ Facebook: https://www.facebook.com/Loisongxanhecolar
▶️Youtube: https://www.youtube.com/@LoiSongXanhEcolar
🎵Tiktok: https://www.tiktok.com/@gaaicapecolar`;

  // Ghép Hashtags và Thông tin liên hệ
  const footer = `${hashtags}\n\n${contactInfo}`;

  // Hàm định dạng và dọn dẹp từng Option
  function cleanAndFormat(opObj) {
    if (!opObj || (typeof opObj === 'object' && Object.keys(opObj).length === 0)) return "";
    if (typeof opObj === 'string') {
      try { opObj = JSON.parse(opObj); } catch (e) { return opObj; }
    }

    let hook = opObj.hook || "";
    let body = opObj.content || "";
    if (typeof body === 'object') body = JSON.stringify(body);

    // Gỡ các nhãn HOOK / NỘI DUNG thừa
    hook = String(hook).replace(/^📌?\s*HOOK\s*:\s*/gi, "").replace(/^\[.*?\]\s*/gim, "").trim();
    body = String(body).replace(/^📝?\s*NỘI DUNG\s*:\s*/gi, "").replace(/^\[.*?\]\s*/gim, "").trim();

    // Ghép Hook & Body
    let fullText = "";
    if (hook && !body.toLowerCase().includes(hook.toLowerCase())) {
      const hasEmoji = /^[\u{1F300}-\u{1F9FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/u.test(hook);
      const hookFormatted = hasEmoji ? hook : `📌 ${hook}`;
      fullText = `${hookFormatted}\n\n${body}`;
    } else {
      fullText = body;
    }

    // Dọn dẹp tên thương hiệu Ecolar chuẩn mực & gỡ nhãn AI
    fullText = fullText
      .replace(/\[\s*Nội dung (do|được)?\s*AI\s*(tạo|sáng tạo|sinh)?\s*\]/gi, "")
      .replace(/\(\s*Nội dung (do|được)?\s*AI\s*(tạo|sáng tạo|sinh)?\s*\)/gi, "")
      .replace(/Nội dung (do|được)?\s*AI\s*(tạo|sáng tạo|sinh)?/gi, "")
      .replace(/AI-generated\s*content/gi, "")
      .replace(/Nông\s+Nghiệp\s+Ecolar/gi, "Ecolar")
      .replace(/Nông\s+nghiệp\s+Ecolar/gi, "Ecolar")
      .replace(/nông\s+nghiệp\s+Ecolar/gi, "Ecolar")
      .replace(/Công\s+ty\s+Ecolar/gi, "Ecolar")
      .replace(/\n{3,}/g, "\n\n")
      .trim();

    return fullText;
  }

  const text1 = cleanAndFormat(op1);
  const text2 = cleanAndFormat(op2);
  const text3 = cleanAndFormat(op3);

  // 5. CHUẨN HÓA DỮ LIỆU ĐẦU RA CHO CỘT GOOGLE SHEETS
  return {
    json: {
      "row_number": rowId,
      "Option_1": text1 ? `${text1}\n\n${footer}`.trim() : rawText,
      "Option_2": text2 ? `${text2}\n\n${footer}`.trim() : "",
      "Option_3": text3 ? `${text3}\n\n${footer}`.trim() : "",
      "Anh_Demo": folderLink,
      "Trạng thái": "waiting_review"
    }
  };
});

// Node: Lấy Option được chọn + Format Nội Dung + Lấy Folder ID Kho Media Drive
return $input.all().map((item, index) => {
  const row = item.json;
  const rowId = row["row_number"] || row["ID"] || (index + 5);
  const keys = Object.keys(row);

  // Hàm trợ giúp tìm tên cột linh hoạt (tránh lỗi viết hoa/thường hoặc thừa dấu cách)
  const findKey = (needle, fallback) =>
    keys.find(k => k.trim().toLowerCase() === needle) ||
    keys.find(k => k.trim().toLowerCase().includes(needle)) || fallback;

  const keyOp1      = findKey("option 1", "Option 1 ");
  const keyOp2      = findKey("option 2", "Option 2");
  const keyOp3      = findKey("option 3", "Option 3");
  const keyDuyetOp  = findKey("duyệt option", "Duyệt Option");

  // Ưu tiên đọc link Kho Media Drive (chứa ảnh thô đầu vào của bài)
  const keyKhoMedia = findKey("kho media drive", "") || findKey("kho media", "") || findKey("ảnh demo", "Ảnh Demo");

  const rawSelectedOp = String(row[keyDuyetOp] || "").trim();
  if (!rawSelectedOp) {
    return { json: {
      ID: rowId,
      selectedOp: "CHƯA_CHỌN",
      folder_id: "",
      fullMessage: "⚠️ CHƯA CHỌN OPTION Ở CỘT 'Duyệt Option'",
      "Kết quả": "no_option_selected_error"
    } };
  }

  // Xác định người dùng chọn Option 1, 2 hay 3
  let optNum = 1;
  if (rawSelectedOp.includes("2")) optNum = 2;
  else if (rawSelectedOp.includes("3")) optNum = 3;

  const textByOpt = { 1: row[keyOp1], 2: row[keyOp2], 3: row[keyOp3] };
  let cleaned = String(textByOpt[optNum] || "")
    .replace(/🖼️\s*(MẪU\s*\d+|PREVIEW\s*ÁNH)\s*:\s*\S+/gi, "")
    .replace(/^\[.*?\]\s*/, "")
    .replace(/^📌\s*HOOK\s*:\s*/gim, "")
    .replace(/^📝\s*NỘI DUNG\s*:\s*/gim, "")
    .replace(/👉\s*Chi tiết tại:[\s\S]*$/i, "")
    .trim();

  // Bóc tách Hashtags ở cuối bài
  const hashtagRegex = /((?:#[\wÀ-ɏḀ-ỿ]+\s*)+)$/i;
  const m = cleaned.match(hashtagRegex);
  let mainText = cleaned, hashtags = "";
  if (m) { 
    hashtags = m[1].trim(); 
    mainText = cleaned.slice(0, m.index).trim(); 
  }

  // Khối thông tin liên hệ chuẩn Ecolar
  const contactInfo = `------------------------------------
Ecolar – Lối sống xanh bền vững
🌐 Website: https://ecolar.vn/
📞Hotline: 0868 515 668
📧Email: lienhe@ecolar.vn
📘Zalo OA: https://zalo.me/1699772582506373938
ⓕFacebook: https://www.facebook.com/Loisongxanhecolar
▶️Youtube: https://www.youtube.com/@LoiSongXanhEcolar
🎵Tiktok: https://www.tiktok.com/@gaaicapecolar`;

  let fullMessage = `${mainText}\n\n${contactInfo}`;
  if (hashtags) fullMessage += `\n\n${hashtags}`;
  fullMessage = fullMessage.replace(/\n{3,}/g, "\n\n").trim();

  // Bóc tách Folder ID từ đường link Google Drive ở ô Kho Media Drive
  const rawFolder = String(row[keyKhoMedia] || "").trim();
  const fm = rawFolder.match(/folders\/([a-zA-Z0-9_-]{20,})/)
          || rawFolder.match(/[?&]id=([a-zA-Z0-9_-]{20,})/);
  const folderId = fm ? fm[1]
                      : (/^[a-zA-Z0-9_-]{20,}$/.test(rawFolder) ? rawFolder : "");

  return { json: {
    ID: rowId,
    selectedOp: rawSelectedOp,
    selectedContent: mainText,
    folder_id: folderId,
    fullMessage,
    "Kết quả": folderId ? "ready_to_gen_images" : "ready_to_gen_images_no_folder"
  } };
});

